# contract-test-file: tooling
"""Pure closure regression from authenticated original-validator generated bytes."""
import hashlib
import importlib.util
import json
from pathlib import Path
import sys
import unittest

ROOT = Path(__file__).resolve().parents[2]
spec = importlib.util.spec_from_file_location('scripts.ci_rust_wasm', ROOT / 'scripts/ci_rust_wasm.py')
lane = importlib.util.module_from_spec(spec)
sys.modules[spec.name] = lane
spec.loader.exec_module(lane)
FIXTURES = ROOT / 'scripts/tests/fixtures/rust-wasm-checkpoint-40951833663'


class ActualGeneratedRecoveryCheckpointTests(unittest.TestCase):
    def setUp(self):
        self.context = json.loads((FIXTURES / 'context.json').read_bytes())
        self.root = (FIXTURES / 'generated-root.js').read_bytes()
        self.guard = (FIXTURES / 'post-header-guard.js').read_bytes()
        self.body = (FIXTURES / 'sdk-inline.js').read_bytes()
        self.inputs = self.context['packageInputPins']
        self.sdk_name = self.context['sdkSnippet']
        self.crypto_name = self.context['cryptoSnippet']
        # Non-JS entries are inert package-shape placeholders. This suite proves
        # closure of actual JS bytes, never compilation/WASM/runtime acceptance.
        self.files = dict(zip(lane.PACKAGE_FILES, [self.root, b'\0asm\x01\0\0\0', b'export {};', b'export {};']))
        self.files.update({self.sdk_name: self.body, self.crypto_name: lane.SNIPPET_BYTES})

    def test_authentic_root_and_original_refused_guard_are_exact(self):
        self.assertEqual(self.context['source_commit'], '28a1386dff030f13b82685de201fbed72793c65f')
        self.assertEqual(self.context['run_id'], '40951833663')
        self.assertEqual(len(self.root), 164656)
        self.assertEqual(hashlib.sha256(self.root).hexdigest(), '3311789355075c37c9ed118455c45f86a7c7a1f010772962909d76395dd495a6')
        self.assertEqual(len(self.guard), 164483)
        self.assertEqual(hashlib.sha256(self.guard).hexdigest(), '3efc906a5ec6bc70fb5b3ad6e09ee6f301f4f886b3f3b7dda427f9be31ad2c75')
        self.assertEqual(len(self.body), 4310)
        self.assertEqual(hashlib.sha256(self.body).hexdigest(), '1bdc2c5ed63001a8ebc06a79d29a2df60ef357840f4d993a55f96de69a57903b')
        old_sdk_header = ('import * as import2 from "./' + self.sdk_name + '"\n').encode()
        old_crypto_header = lane.package_import_headers(self.crypto_name)[1]
        self.assertEqual(self.root.count(old_sdk_header), 1)
        self.assertEqual(self.root.count(old_crypto_header), 1)
        self.assertEqual(self.root.replace(old_sdk_header, b'', 1).replace(old_crypto_header, b'', 1), self.guard)
        self.assertEqual(lane.module_dependency_reason(self.guard), 4)
        self.assertFalse(lane.closed_module_dependencies(self.guard))

    def test_exact_observed_graph_closes_without_changing_emitted_bytes(self):
        original = dict(self.files)
        state = {}
        self.assertTrue(lane.package_modules(self.files, self.inputs, state))
        self.assertTrue(state['packageDependenciesClosed'])
        self.assertTrue(state['packageSdkNamespaceUsesClosed'])
        self.assertEqual(self.files, original)
        view = lane.recovery_sdk_output(self.files, self.inputs)
        self.assertNotIn(self.sdk_name, view)
        self.assertEqual(view[self.crypto_name], lane.SNIPPET_BYTES)
        reduced = view[lane.PACKAGE_FILES[0]].replace(lane.package_import_headers(self.crypto_name)[1], b'', 1)
        self.assertEqual(lane.module_dependency_reason(reduced), 0)
        self.assertTrue(lane.closed_module_dependencies(reduced))
        self.assertEqual(lane.module_dependency_reason(self.guard), 4)

    def test_every_original_selected_source_pin_remains_required(self):
        for path in self.inputs:
            for bad in (None, '0' * 64):
                with self.subTest(path=path, bad=bad):
                    changed = dict(self.inputs)
                    changed[path] = bad
                    self.assertFalse(lane.package_modules(self.files, changed))

    def test_observed_headers_calls_maps_and_aliases_cannot_drift(self):
        namespace3 = ('import * as import3 from "./' + self.sdk_name + '"\n').encode()
        namespace4 = ('import * as import4 from "./' + self.sdk_name + '"\n').encode()
        mutations = [
            self.root + b'\n',
            self.root + b"import('./other.js');",
            self.root + b"import('./other.js')",
            self.root + b"export * from './other.js';",
            self.root + b"const escaped='\\u0069mport';",
            self.root.replace(namespace3, b'', 1),
            self.root.replace(namespace4, b'', 1),
            self.root.replace(namespace3, namespace3 * 2, 1),
            self.root.replace(namespace4, namespace4 * 2, 1),
            self.root.replace(b'import3,', b'import3["recoveryRead"],', 1),
            self.root.replace(b'import4,', b'aliasedSdk,', 1),
            self.root.replace(b'recoveryRead(arg0, arg1)', b'recoveryOther(arg0, arg1)', 1),
            self.root.replace(b'recoveryRead, recoveryRequest', b'recoveryRead as aliasRead, recoveryRequest', 1),
            self.root.replace(b'inline0.js": import4', b'other.js": import4', 1),
        ]
        for changed in mutations:
            with self.subTest(digest=hashlib.sha256(changed).hexdigest()):
                self.assertNotEqual(changed, self.root)
                files = dict(self.files)
                files[lane.PACKAGE_FILES[0]] = changed
                self.assertFalse(lane.package_modules(files, self.inputs))

    def test_actual_module_bodies_and_physical_inventory_remain_closed(self):
        for name in (self.sdk_name, self.crypto_name):
            changed = dict(self.files)
            changed[name] += b' '
            self.assertFalse(lane.package_modules(changed, self.inputs))
            changed = dict(self.files)
            del changed[name]
            self.assertFalse(lane.package_modules(changed, self.inputs))
        changed = dict(self.files)
        changed['extra.js'] = b'export {};'
        self.assertFalse(lane.package_modules(changed, self.inputs))
        changed = dict(self.files)
        del changed[self.sdk_name]
        changed[self.sdk_name.replace('c8cc119936fa2be8', 'c8cc119936fa2be9')] = self.body
        self.assertFalse(lane.package_modules(changed, self.inputs))


if __name__ == '__main__':
    unittest.main()
